void OperatorPanel::scenesDialog(){run([this]{
    if(!leaveDraft())return;QDialog dialog(this);dialog.setObjectName("jpProjectsDialog");dialog.setWindowTitle("Cenas · projetos e eventos");dialog.resize(760,590);auto *root=new QVBoxLayout(&dialog);
    auto *note=new QLabel("Cada evento possui sua própria biblioteca e posições. Abrir um projeto preserva o programa do OBS.",&dialog);note->setWordWrap(true);root->addWidget(note);auto *list=new QListWidget(&dialog);list->setObjectName("jpProjectList");root->addWidget(list,1);
    auto selected=[&]{auto *item=list->currentItem();if(!item)throw Error("Selecione um projeto.");return item->data(Qt::UserRole).toString();};
    auto refresh=[&]{QString current=list->currentItem()?list->currentItem()->data(Qt::UserRole).toString():c_.projectId();list->clear();for(const auto &v:c_.store.snapshot()["projects"].toArray()){const auto p=v.toObject();const auto pid=p["id"].toString();const int onAir=int(c_.confirmedProjects.value(pid).size());auto *item=new QListWidgetItem(p["name"].toString()+(pid==c_.projectId()?" · ATIVO":"")+(onAir?QString(" · %1 NO AR").arg(onAir):QString()),list);item->setData(Qt::UserRole,pid);item->setToolTip(QString("%1 conteúdos · ID %2").arg(p["media"].toArray().size()).arg(pid));if(pid==current)list->setCurrentItem(item);}if(!list->currentItem()&&list->count())list->setCurrentRow(0);};
    connect(&c_.store,&Store::changed,&dialog,refresh);auto *actions=new QGridLayout;root->addLayout(actions);int n=0;
    auto add=[&](const QString &label,const QString &name,const std::function<void()> &fn){auto *b=new QPushButton(label,&dialog);b->setObjectName(name);actions->addWidget(b,n/3,n%3);++n;connect(b,&QPushButton::clicked,&dialog,[this,fn]{run(fn);});};
    add("Abrir projeto","jpProjectOpen",[&]{c_.switchProject(selected());dialog.accept();});
    add("Criar projeto…","jpProjectCreate",[&]{bool ok=false;const auto name=QInputDialog::getText(&dialog,"Criar projeto","Nome do evento",QLineEdit::Normal,{},&ok);if(ok&&!name.trimmed().isEmpty()){const auto id=c_.store.createProject(name);c_.switchProject(id);dialog.accept();}});
    add("Renomear…","jpProjectRename",[&]{const auto pid=selected();bool ok=false;const auto name=QInputDialog::getText(&dialog,"Renomear projeto","Nome do evento",QLineEdit::Normal,c_.store.project(pid)["name"].toString(),&ok);if(ok)c_.store.renameProject(pid,name);});
    add("Duplicar projeto…","jpProjectDuplicate",[&]{const auto pid=selected();bool ok=false;const auto name=QInputDialog::getText(&dialog,"Duplicar projeto","Nome da cópia",QLineEdit::Normal,c_.store.project(pid)["name"].toString()+" (cópia)",&ok);if(ok){const auto id=c_.store.duplicateProject(pid,name);refresh();for(int i=0;i<list->count();++i)if(list->item(i)->data(Qt::UserRole).toString()==id)list->setCurrentRow(i);c_.notify("Projeto duplicado. Mídias físicas compartilhadas; a cópia começa fora do ar.");}});
    add("Excluir projeto…","jpProjectDelete",[&]{const auto pid=selected();if(!c_.confirmedProjects.value(pid).isEmpty())throw Error("O projeto ainda está no ar. Retire seus conteúdos antes de excluir.");for(const auto &v:c_.store.project(pid)["media"].toArray())if(v.toObject()["live"].isObject())throw Error("O projeto possui conteúdos publicados. Execute Out antes de excluir.");if(QMessageBox::question(&dialog,"Excluir projeto","Excluir este projeto? Os arquivos originais e os binários no cache serão preservados.",QMessageBox::Yes|QMessageBox::No,QMessageBox::No)==QMessageBox::Yes)c_.store.removeProject(pid);});
    add("Importar projeto…","jpProjectImport",[&]{const auto path=QFileDialog::getExistingDirectory(&dialog,"Pasta do projeto exportado");if(!path.isEmpty())c_.store.importProjectAsync(path);});
    add("Exportar projeto…","jpProjectExport",[&]{const auto path=QFileDialog::getExistingDirectory(&dialog,"Pasta vazia para exportação");if(!path.isEmpty())c_.store.exportProjectAsync(selected(),path);});
    add("Pasta da biblioteca","jpLibraryFolder",[&]{QDesktopServices::openUrl(QUrl::fromLocalFile(c_.store.root()));});
    add("Histórico e diagnóstico","jpHistory",[&]{QMessageBox::information(&dialog,"Diagnóstico",c_.obsStatus+"\n\n"+c_.history.join('\n'));});
    connect(list,&QListWidget::itemDoubleClicked,&dialog,[&]{run([&]{c_.switchProject(selected());dialog.accept();});});auto *close=new QDialogButtonBox(QDialogButtonBox::Close,&dialog);root->addWidget(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);refresh();dialog.exec();
});}
void OperatorPanel::contentProperties(){run([this]{
    const auto m=c_.selected();if(m.isEmpty())throw Error("Selecione um conteúdo.");const auto pid=c_.projectId(),id=c_.selectedId;QDialog dialog(this);dialog.setWindowTitle("Editar conteúdo");dialog.setObjectName("jpContentProperties");dialog.resize(540,620);auto *root=new QVBoxLayout(&dialog);auto *form=new QFormLayout;
    auto *name=new QLineEdit(m["name"].toString(),&dialog),*group=new QLineEdit(m["group"].toString(),&dialog);name->setMaxLength(120);group->setMaxLength(120);auto *category=new QComboBox(&dialog);for(const auto &v:c_.project()["categories"].toArray())category->addItem(v.toString());category->setCurrentText(m["category"].toString());form->addRow("Nome",name);form->addRow("Categoria",category);form->addRow("Grupo",group);
    auto *loop=new QCheckBox("Reproduzir em loop",&dialog);loop->setChecked(m["draft"].toObject()["loop"].toBool(true));loop->setEnabled(m["mime"].toString().startsWith("video/"));form->addRow(loop);auto *end=new QComboBox(&dialog);end->addItem("Manter último quadro","hold");end->addItem("Retirar do ar","out");end->setCurrentIndex(qMax(0,end->findData(m["draft"].toObject()["endBehavior"].toString("hold"))));end->setEnabled(loop->isEnabled());form->addRow("Ao terminar",end);
    auto *disabled=new QCheckBox("Desativado para operação",&dialog);disabled->setChecked(m["disabled"].toBool());form->addRow(disabled);QMap<QString,QLineEdit*> text;
    if(m["mime"]=="application/x-jp-title")for(const auto &key:QStringList{"name","role","city"}){auto *field=new QLineEdit(m["draft"].toObject()["text"].toObject()[key].toString(),&dialog);field->setMaxLength(500);text[key]=field;form->addRow(key=="name"?"Pessoa":key=="role"?"Cargo":"Cidade",field);}
    auto *transition=new QComboBox(&dialog);for(const auto &pair:QList<QPair<QString,QString>>{{"none","Sem transição"},{"fade","Dissolver"},{"left","Pela esquerda"},{"right","Pela direita"},{"bottom","Por baixo"},{"scale","Escala"}})transition->addItem(pair.second,pair.first);transition->setCurrentIndex(qMax(0,transition->findData(m["draft"].toObject()["transition"].toString("fade"))));form->addRow("Transição",transition);auto *duration=new QSpinBox(&dialog);duration->setRange(0,3000);duration->setValue(m["draft"].toObject()["duration"].toInt(300));form->addRow("Duração · ms",duration);auto *opacity=new QDoubleSpinBox(&dialog);opacity->setRange(0,100);opacity->setValue(m["draft"].toObject()["opacity"].toDouble(100));form->addRow("Opacidade · %",opacity);auto *layer=new QSpinBox(&dialog);layer->setRange(-10000,10000);layer->setValue(m["draft"].toObject()["z"].toInt());form->addRow("Camada",layer);
    auto *fieldsWidget=new QWidget(&dialog);fieldsWidget->setLayout(form);auto *scroll=new QScrollArea(&dialog);scroll->setWidgetResizable(true);scroll->setWidget(fieldsWidget);root->addWidget(scroll,1);auto *note=new QLabel("O posicionamento compartilhado é configurado em Editar posição.",&dialog);root->addWidget(note);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel,&dialog);root->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{run([&]{if(category->currentText()!=m["category"].toString()&&(c_.onAir(id)||m["live"].isObject()))throw Error("Execute Out antes de mudar a categoria.");QJsonObject patch{{"name",name->text()},{"group",group->text()},{"category",category->currentText()},{"disabled",disabled->isChecked()},{"draft",QJsonObject{{"loop",loop->isChecked()},{"endBehavior",end->currentData().toString()},{"transition",transition->currentData().toString()},{"duration",duration->value()},{"opacity",opacity->value()},{"z",layer->value()}}}};if(!text.isEmpty()){QJsonObject value;for(auto it=text.begin();it!=text.end();++it)value[it.key()]=it.value()->text();patch["text"]=value;}c_.store.updateMedia(pid,id,patch);dialog.accept();});});dialog.exec();
});}
void OperatorPanel::linkDialog(){run([this]{
    if(c_.projectId().isEmpty())throw Error("Crie um projeto em Cenas.");const auto pid=c_.projectId();QDialog dialog(this);dialog.setObjectName("jpLinkDialog");dialog.setWindowTitle("Link OBS · conexão e cenas reais");dialog.resize(850,700);auto *root=new QVBoxLayout(&dialog);root->addWidget(new QLabel("Projeto: "+c_.project()["name"].toString(),&dialog));auto *tabs=new QTabWidget(&dialog);root->addWidget(tabs,1);auto *connection=new QWidget(tabs);auto *form=new QFormLayout(connection);auto *mode=new QComboBox(connection);mode->setObjectName("jpConnectionMode");mode->addItem("OBS local · integração nativa","native");mode->addItem("OBS WebSocket 5","websocket");const auto config=c_.project()["obsLink"].toObject();mode->setCurrentIndex(qMax(0,mode->findData(config["mode"].toString("native"))));form->addRow("Conexão",mode);
    auto *host=new QLineEdit(config["host"].toString("127.0.0.1"),connection);host->setObjectName("jpObsHost");auto *port=new QSpinBox(connection);port->setObjectName("jpObsPort");port->setRange(1,65535);port->setValue(config["port"].toInt(4455));auto *password=new QLineEdit(connection);password->setObjectName("jpObsPassword");password->setEchoMode(QLineEdit::Password);auto *tls=new QCheckBox("Conexão segura · WSS",connection);tls->setChecked(config["tls"].toBool());form->addRow("Endereço do OBS",host);form->addRow("Porta",port);form->addRow("Senha",password);form->addRow(tls);auto *mediaRoot=new QLineEdit(config["mediaRoot"].toString(),connection);mediaRoot->setObjectName("jpObsMediaRoot");mediaRoot->setPlaceholderText("Vazio: biblioteca no mesmo computador");form->addRow("Pasta da biblioteca no OBS",mediaRoot);auto *status=new QLabel(c_.obsStatus,connection);status->setWordWrap(true);form->addRow(status);
    auto updateMode=[&]{const bool ws=mode->currentData()=="websocket";for(auto *widget:QList<QWidget*>{host,port,password,tls,mediaRoot})widget->setEnabled(ws);};connect(mode,&QComboBox::currentIndexChanged,&dialog,updateMode);updateMode();
    auto *connectButton=new QPushButton("Salvar e conectar",connection),*disconnect=new QPushButton("Desconectar",connection);form->addRow(connectButton,disconnect);
    connect(connectButton,&QPushButton::clicked,&dialog,[&]{run([&]{const QJsonObject settings{{"mode",mode->currentData().toString()},{"host",host->text()},{"port",port->value()},{"tls",tls->isChecked()},{"mediaRoot",mediaRoot->text()}};if(!c_.connectionRequested)throw Error("Integração de conexão indisponível.");c_.connectionRequested(settings,password->text());});});connect(disconnect,&QPushButton::clicked,&dialog,[&]{c_.link(false);});connect(&c_,&Controller::changed,&dialog,[&]{status->setText(c_.obsStatus);});tabs->addTab(connection,"Conexão");
    auto *scenePage=new QWidget(tabs);auto *sceneLayout=new QVBoxLayout(scenePage);auto *scenes=new QListWidget(scenePage);scenes->setObjectName("jpObsSceneList");scenes->setSelectionMode(QAbstractItemView::ExtendedSelection);sceneLayout->addWidget(scenes,1);auto *sources=new QListWidget(scenePage);sources->setObjectName("jpObsSources");sceneLayout->addWidget(sources,1);auto *category=new QComboBox(scenePage);category->addItem("Todas as categorias","");for(const auto &cat:panelCategories())category->addItem(cat,cat);sceneLayout->addWidget(category);
    auto details=[&]{sources->clear();for(auto *entry:scenes->selectedItems()){const auto data=entry->data(Qt::UserRole+1).value<QJsonObject>();for(const auto &v:data["sources"].toArray()){const auto source=v.toObject();sources->addItem(source["name"].toString()+" · "+(source["project"].toString()==pid?"este projeto":"outro projeto")+" · "+(source["category"].toString().isEmpty()?"todas as categorias":source["category"].toString())+" · "+(source["visible"].toBool()?"visível":"oculta"));}}for(const auto &v:c_.store.project(pid)["obsBindings"].toArray()){const auto b=v.toObject();if(b["missing"].toBool())sources->addItem("FONTE AUSENTE · "+b["sourceName"].toString()+" · "+b["category"].toString());}};
    auto refresh=[&]{QSet<QString> selection;for(auto *i:scenes->selectedItems())selection.insert(i->data(Qt::UserRole).toString());scenes->clear();const auto state=c_.obsScenes.isEmpty()&&c_.scenes?c_.scenes():c_.obsScenes;for(const auto &v:state){const auto row=v.toObject();auto *item=new QListWidgetItem(row["name"].toString(),scenes);item->setData(Qt::UserRole,row["uuid"].toString(row["name"].toString()));item->setData(Qt::UserRole+1,row);if(selection.contains(item->data(Qt::UserRole).toString()))item->setSelected(true);}if(scenes->selectedItems().isEmpty()&&scenes->count())scenes->setCurrentRow(0);details();};connect(scenes,&QListWidget::itemSelectionChanged,&dialog,details);connect(&c_,&Controller::obsScenesChanged,&dialog,refresh);
    auto *row=new QHBoxLayout;auto add=[&](const QString &label,const QString &command,bool enabled){auto *b=new QPushButton(label,scenePage);row->addWidget(b);connect(b,&QPushButton::clicked,&dialog,[&,command,enabled]{run([&]{if(!c_.online||!c_.sceneAction)throw Error("Conecte ao OBS.");if(scenes->selectedItems().isEmpty())throw Error("Selecione ao menos uma cena.");for(auto *item:scenes->selectedItems())c_.sceneAction(item->data(Qt::UserRole).toString(),command,enabled,category->currentData().toString());if(c_.scenesRefresh)c_.scenesRefresh();refresh();});});};add("Associar composição","associate",true);add("Mostrar vínculo","visible",true);add("Ocultar vínculo","visible",false);sceneLayout->addLayout(row);auto *reload=new QPushButton("Atualizar cenas, fontes e vínculos",scenePage);sceneLayout->addWidget(reload);connect(reload,&QPushButton::clicked,&dialog,[&]{run([&]{if(c_.scenesRefresh)c_.scenesRefresh();refresh();});});auto *note=new QLabel("Associe somente composições gerenciadas deste projeto. O nome do evento é independente do nome da cena. Fontes de terceiros são preservadas.",scenePage);note->setWordWrap(true);sceneLayout->addWidget(note);tabs->addTab(scenePage,"Cenas e fontes do OBS");refresh();
    auto *close=new QDialogButtonBox(QDialogButtonBox::Close,&dialog);root->addWidget(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();
});}
